package ru.projectkingdom.npc;import net.minecraft.world.item.*;import net.minecraft.server.level.*;public class KingdomCurrency {public static class Coin {public net.minecraft.world.item.Item item;public Coin(String name){item=new net.minecraft.world.item.Item(name);}public net.minecraft.world.item.Item get(){return item;}}public static final Coin COPPER=new Coin("copper"),SILVER=new Coin("silver"),GOLD=new Coin("gold"),WALLET=new Coin("wallet");public static long value(net.minecraft.world.item.ItemStack s){if(s.is(GOLD.get()))return 10000;if(s.is(SILVER.get()))return 100;if(s.is(COPPER.get()))return 1;return 0;}public static ItemStack wallet(ServerPlayer p){return p.inventory.wallet;}public static long balance(ItemStack w){return w.money;}public static boolean debit(ItemStack w,long amount){if(amount<1||w.money<amount)return false;w.money-=amount;return true;}public static boolean credit(ItemStack w,long amount){if(amount<1||w.money>Long.MAX_VALUE-amount)return false;w.money+=amount;return true;}}